    }

    public void forComponent(Component x) {"""
t = t.replace("\n    public void forComponent(Component x) {", helper, 1)
io.open(shadow + "/com/sun/fortress/compiler/codegen/CodeGen.java", "w", encoding="utf-8").write(t)
print("shadow sources written")
